settings.liquid:
{%- assign bundleandsave = false -%}

{%- if product.tags contains 'bundleandsave' -%}
  {%- assign bundleandsave = true -%}
{%- endif -%}

{% assign tagline = nil %}
{%- if product.metafields.custom.tagline -%}
  {%- assign tagline = product.metafields.custom.tagline -%}
{%- endif -%}

{%- if collection -%}
  {%- if collection.metafields.custom.tagline and collection.metafields.accentuate.collection_tagline_overwrite -%}
    {%- assign tagline = collection.metafields.custom.tagline -%}
  {%- endif -%}
{%- endif -%}

{% if tagline != blank %}
  {%- if hidden -%}
    {%- if tagline contains 'code:' or tagline contains 'CODE:' or tagline contains 'Code:' -%}
      <input type="hidden" value="{{ tagline | escape }}" name="properties[Promo]"/>
    {%- endif -%}
  {%- else -%}
    <!--Snippets: product-tagline:19-->
    <p class="cProductCard-tagline {% if bundleandsave %}cProductCard-tagline--large{% endif %}">{{ tagline }}</p>
  {%- endif -%}
{% endif %}

{% assign hideuk-PDPTAG4 = false %}
              {% if localization.country.iso_code == 'GB' %}
                {% for tag in product.tags %}
                  {% if tag == 'hideuk-PDPTAG4' %}
                    {% assign hideuk-PDPTAG4 = true %}
                    {% break %}
                  {% endif %}
                {% endfor %}
              {% endif %}
              {% unless hideuk-PDPTAG4 %}
          {% assign show_taglist = false %}
            {% for tag in product.tags %}
              {% if tag contains "PDPTAG4-" %}
                {% assign show_taglist = true %}
              {% endif %}
            {% endfor %}
            {% if show_taglist and request.page_type == "collection" or request.page_type == "product" and show_taglist %}
              <div class="tg4-taglist-main tag4">
              {% for tag in product.tags %}
                {% if tag contains "PDPTAG4-" %}
                  {% assign tag_parts = tag | split: "-" %}
                  {% assign hascode = tag_parts[1] %}
                  {% assign tag_label = tag_parts[2] %}
                  <div class="tg4-tag-custom" style="--tag4color:#{{ hascode }};">
                    {{ tag_label }}
                  </div>
                {% break %}
                {% endif %}
              {% endfor %}
              </div>
            {% endif %}
            {% endunless %}

{% assign hideuk-PDPTAG3 = false %}
              {% if localization.country.iso_code == 'GB' %}
                {% for tag in product.tags %}
                  {% if tag == 'hideuk-PDPTAG3' %}
                    {% assign hideuk-PDPTAG3 = true %}
                    {% break %}
                  {% endif %}
                {% endfor %}
              {% endif %}
              {% unless hideuk-PDPTAG3 %}
{% if product.metafields.custom.short_description  %}
              <div class="tg3-taglist-main tag3">
                  <div class="tg3-tag-custom" style="--tag3color:#000000;">
                    {{ product.metafields.custom.short_description }}
                  </div>
              </div>
            {% endif %}
            {% endunless %}

{% assign hide = true %}
{% assign hidesizescale = true %}
<div class="size-wrapper">
{% for tag in product.tags %}
        {% if tag contains 'size_chart:' %}
            {% assign current_tag = tag | replace: 'size_chart:', '' | strip | handle %}
            {% assign hide = false %}
            <a href="#modal-size-{{- current_tag -}}" class="size-guide-new no-toggle toggle js-modal-alt" onclick="initTriggers()">Size Guide</a>
        {% endif %}
      {% endfor %}
{% if product.metafields.custom.size_scale_product %}
    {% assign hidesizescale = false %}
    <div class="size-scale">
        {{ product.metafields.custom.size_scale_product }}
    </div>
{% endif %}
      {% if hide and hidesizescale %}
      <div class="hide-sizeguide"></div>
      {% endif %}
</div>

{% for tag in product.tags %}
        {% if tag contains 'size_chart:' %}
            {% assign current_tag = tag | replace: 'size_chart:', '' | strip | handle %}

            <a href="#modal-size-{{- current_tag -}}" class="accordion-size
 size-guide-new toggle js-modal-alt">Size Chart <span class="animated-plus group-expanded:rotate" aria-hidden="true"></span>
</a>
        {% endif %}
      {% endfor %}

{% assign hide = true %}
{% assign hidecont = true %}
{% assign is_uk = false %}
{% if localization.country.iso_code == 'GB' %}
  {% assign is_uk = true %}
{% endif %}

{% if is_uk and product.metafields.custom.size_fit_content_uk %}
  {% assign hidecont = false %}
  <div class="size-fit-content">
    {{ product.metafields.custom.size_fit_content_uk }}
  </div>
{% elsif product.metafields.custom.size_fit_content %}
  {% assign hidecont = false %}
  <div class="size-fit-content">
    {{ product.metafields.custom.size_fit_content }}
  </div>
{% endif %}

{% for tag in product.tags %}
  {% if tag contains 'size_chart:' %}
    {% assign current_tag = tag | replace: 'size_chart:', '' | strip | handle %}
    {% assign hide = false %}
    <a href="#modal-size-{{ current_tag }}" class="size-guide-new toggle js-modal-alt">
      Size Chart
    </a>
  {% endif %}
{% endfor %}

{% if hide and hidecont %}
  <div class="hide-sizeguide"></div>
{% endif %}

{% unless product.category == "Gift Cards" %}
<div class="inner" {% if collapsed %}style="display: none;"{% endif %}>
            {{ product.metafields.accentuate.the_specifics | default: product.metafields.custom.the_specifics }}
        </div> 
{% endunless %}
